import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const dir=path.dirname(fileURLToPath(import.meta.url));const kit=path.resolve(dir,'../../..');const repo=path.resolve(kit,'..');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const temp=fs.mkdtempSync(path.join(os.tmpdir(),'botsales-fe003-evidence-probe-'));const probeKit=path.join(temp,'kit');const probeSrc=temp;
for(const p of ['scripts','execution/frontend-evidence/FE003'])fs.mkdirSync(path.join(probeKit,p),{recursive:true});
fs.copyFileSync(path.join(kit,'scripts/progress.mjs'),path.join(probeKit,'scripts/progress.mjs'));
fs.copyFileSync(path.join(kit,'release.json'),path.join(probeKit,'release.json'));
const fullPlan=read(path.join(kit,'execution/frontend-plan.json'));const originalTask=fullPlan.tasks.find(t=>t.id==='FE003');
const step=structuredClone(originalTask.implementationSteps.find(s=>s.id==='S04'));
const plan={...fullPlan,tasks:[{...originalTask,dependsOn:[],implementationSteps:[step]}]};const planBytes=Buffer.from(JSON.stringify(plan,null,2)+'\n');fs.writeFileSync(path.join(probeKit,'execution/frontend-plan.json'),planBytes);
const state={version:'1.0',planId:plan.planId,planSha256:sha(planBytes),revision:0,scope:'FRONTEND_WITH_SYNTHETIC_MOCK_API',sourceRootRelative:'..',tasks:{FE003:{status:'IN_PROGRESS',owner:'isolated-probe',blockedReason:null,steps:{S04:{status:'NOT_STARTED',evidence:null}}}},history:[]};
fs.writeFileSync(path.join(probeKit,'execution/frontend-progress.json'),JSON.stringify(state,null,2)+'\n');
fs.writeFileSync(path.join(probeSrc,'fixture.txt'),'isolated evidence-validator fixture\n');
fs.writeFileSync(path.join(probeKit,'execution/frontend-evidence/FE003/probe.log'),'isolated validator probe; no product test\n');
const logHash=sha(fs.readFileSync(path.join(probeKit,'execution/frontend-evidence/FE003/probe.log')));const sourceHash=sha(fs.readFileSync(path.join(probeSrc,'fixture.txt')));const snapshot=sha(Buffer.from(`fixture.txt:${sourceHash}`));
const base={taskId:'FE003',stepId:'S04',kind:'artifact_review',result:'PASS',verificationScope:'FRONTEND_WITH_SYNTHETIC_MOCK_API',executedAt:new Date().toISOString(),sourceRevision:'ISOLATED-EVIDENCE-VALIDATOR-PROBE',expected:'Verify evidence validator rejects malformed scope/log in a disposable reduced-plan copy.',observed:'Negative probe only; not product evidence.',command:'isolated evidence validator checkpoint probe',cwd:repo,reviewer:'Codex isolated probe',environment:{name:'Isolated Node validator test',details:'Temporary copy of progress.mjs and reduced test plan; no app source or live ledger mutation.',dataSource:'source-only'},checksTotal:1,failed:0,sourceFiles:[{path:'fixture.txt',sha256:sourceHash}],sourceSnapshotSha256:snapshot,logFile:'execution/frontend-evidence/FE003/probe.log',logSha256:logHash};
const statePath=path.join(probeKit,'execution/frontend-progress.json');const before=sha(fs.readFileSync(statePath));
function attempt(name,evidence){const out=path.join(probeKit,`execution/frontend-evidence/FE003/${name}.json`);fs.writeFileSync(out,JSON.stringify(evidence,null,2)+'\n');const p=spawnSync(process.execPath,[path.join(probeKit,'scripts/progress.mjs'),'checkpoint','FE003','S04',`execution/frontend-evidence/FE003/${name}.json`],{cwd:probeKit,encoding:'utf8'});const output=(p.stdout||'')+(p.stderr||'');return {name,exit:p.status,message:output.trim()};}
const wrongScope=attempt('wrong-scope',{...base,verificationScope:'WRONG_SCOPE'});
const missingLog=attempt('missing-log',{...base,logFile:'execution/frontend-evidence/FE003/no-such-log.log'});
const after=sha(fs.readFileSync(statePath));
const report={scope:'ISOLATED_TRACKER_EVIDENCE_VALIDATOR_ONLY',temp,wrongScope,missingLog,liveLedgerChanged:false,probeStateUnchanged:before===after};
if(wrongScope.exit!==1||!wrongScope.message.includes('Frontend evidence must declare its mock API verification scope')||missingLog.exit!==1||!missingLog.message.includes('Missing evidence/source file')||before!==after)throw new Error('Evidence validator negative probes failed');
const outPath=path.join(kit,'execution/frontend-evidence/FE003/S04-evidence-probes-post-fe002-current-20261006.json');fs.writeFileSync(outPath,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
